use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};
const R:&str="/home/ubuntu/src/zopro-perf-work/borrowed-pair178";
const OLD:&str="/home/ubuntu/src/zopro-perf-work/packed-ternary176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(n:&str,v:Value){fs::write(format!("{R}/{n}"),serde_json::to_vec_pretty(&v).unwrap()).unwrap()}
fn prepare(){
 assert_eq!(read(format!("{R}/result.json"))["advance_to_full_proof_qualification"],false);
 let old=read(format!("{OLD}/diagnostic-plan.json"));let mut steps=vec![];let mut env=read(format!("{R}/environment.json"));env["ZOPRO_BENCH_PERF_CTL"]=format!("{R}/ctl").into();env["ZOPRO_BENCH_PERF_ACK"]=format!("{R}/ack").into();env["RAYON_NUM_THREADS"]="32".into();
 for panel in["stat","cycles","decode"]{let modes=if panel=="cycles"{vec![2,1,0]}else{vec![0,1,2]};for mode in modes{
  for oldstep in old["steps"].as_array().unwrap().iter().filter(|s|{let n=s["name"].as_str().unwrap();n.ends_with("OLD_BASE")&&match panel{"stat"=>n.starts_with("stat-"),"cycles"=>n.starts_with("cycles-"),_=>!n.starts_with("stat-")&&!n.starts_with("cycles-")}}){
   let mut step=oldstep.clone();let name=step["name"].as_str().unwrap().replace("OLD_BASE",&format!("M{mode}"));step["name"]=name.into();let mut argv=step["argv"].as_array().unwrap().iter().map(|x|x.as_str().unwrap().replace(OLD,R).replace("OLD_BASE",&format!("M{mode}")).replace("/home/ubuntu/src/zopro-perf-work/ternary-reciprocal-codec176/candidate-bin",&format!("{R}/bin/copy0"))).collect::<Vec<_>>();
   if panel!="decode"{let at=argv.iter().position(|s|s=="perf").unwrap();let rest=argv.split_off(at);argv=vec!["sudo".into(),"-n".into(),"env".into()];let mut e=env.clone();e["ZOPRO_DIAGNOSTIC_PAIR_MODE"]=mode.to_string().into();for(k,v)in e.as_object().unwrap(){argv.push(format!("{k}={}",v.as_str().unwrap()));}argv.extend(rest);}
   step["argv"]=json!(argv);steps.push(step);
  }
 }}
 for d in["stat","perf"]{fs::create_dir_all(format!("{R}/{d}")).unwrap();}
 let mut pins=read(format!("{R}/capture-pins.json")).as_object().unwrap().clone();for p in[format!("{R}/diagnose.rs"),format!("{R}/diagnostic-protocol.md"),"/home/ubuntu/src/zopro-perf-work/window-batch-proof-capture176/campaign".into()]{pins.insert(p.clone(),hash(&p).into());}save("diagnostic-pins.json",json!(pins));save("diagnostic-plan.json",json!({"version":1,"source_pins":format!("{R}/diagnostic-pins.json"),"steps":steps}));println!("Six captures then fifteen decode steps frozen;1380 complete queries.");
}
fn analyze(){
 for(p,h)in read(format!("{R}/diagnostic-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 assert_eq!(read(format!("{R}/diagnostic-run/result.json"))["status"],"complete");let plan=read(format!("{R}/diagnostic-plan.json"));assert_eq!(plan["steps"].as_array().unwrap().len(),21);let mut callers=BTreeMap::new();let mut seconds=0.;
 for step in plan["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();let dir=format!("{R}/diagnostic-run/{name}");let e=read(format!("{dir}/exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);seconds+=e["elapsed_ms"].as_f64().unwrap()/1000.;let command=read(format!("{dir}/command.json"));assert_eq!(&command["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap());for stream in["stdout","stderr"]{assert_eq!(hash(format!("{dir}/{stream}.log")),e[format!("{stream}_sha256")]);}
  if name.starts_with("stat-")||name.starts_with("cycles-"){let text=fs::read_to_string(format!("{dir}/stdout.log")).unwrap();let row:Value=serde_json::from_str(text.trim().strip_prefix("CALLER ").unwrap()).unwrap();let mode=name.chars().last().unwrap().to_digit(10).unwrap();let n=if name.starts_with("stat-"){201}else{251};assert_eq!(row["rounds"],n);assert_eq!(row["mode"],mode);assert_eq!(row["selected_mode"],mode);let mut count=[0;3];count[mode as usize]=n+4;assert_eq!(row["route_status"],json!(count));assert_eq!(row["every_output_matches_independent_full_MSM"],true);assert_eq!(row["point_inputs_unchanged"],true);callers.insert(name.to_owned(),row);}
 }
 assert_eq!(callers.len(),6);let mut quality=true;let mut stats=vec![];let mut profiles=vec![];
 for m in 0..3{
  let csv=fs::read_to_string(format!("{R}/stat/stat-1x2-B-w32-M{m}.csv")).unwrap();let mut counters=BTreeMap::new();for line in csv.lines().filter(|l|!l.is_empty()&&!l.starts_with('#')){let f=line.split(';').collect::<Vec<_>>();assert!(f.len()>=5);let value=f[0].parse::<u64>().ok();let running=f[4].parse::<f64>().ok();let pass=value.is_some()&&running.is_some_and(|x|x>=100.&&x<=100.01);quality&=pass;counters.insert(f[2].to_owned(),json!({"value":value,"per_query":value.map(|x|x as f64/201.),"running_percent":running,"quality_passed":pass}));}assert_eq!(counters.len(),4);for event in["cycles:u","instructions:u","cache-misses:u","branch-misses:u"]{assert!(counters.contains_key(event));}stats.push(json!({"mode":m,"counters":counters}));
  let name=format!("cycles-1x2-B-w32-M{m}");let row=&callers[&name];let pid=row["pid"].as_u64().unwrap();let workers=row["worker_rows"].as_array().unwrap().iter().map(|r|(r["tid"].as_u64().unwrap(),r["cpu"].as_u64().unwrap())).collect::<BTreeMap<_,_>>();let path=|prefix:&str|format!("{R}/diagnostic-run/{prefix}{name}/stdout.log");let metadata=fs::read_to_string(path("metadata-")).unwrap();let events=fs::read_to_string(path("events-")).unwrap();assert!(metadata.contains("PERF_RECORD_COMM")&&metadata.lines().any(|l|l.contains("PERF_RECORD_MMAP")&&l.contains(&format!("{pid}/{pid}"))&&l.contains(&format!("{R}/bin/copy0"))));assert!(events.contains("cycles:u")&&events.contains("16000000")&&events.contains("CPU|PERIOD")&&events.contains("exclude_kernel: 1")&&events.contains("inherit: 1"));let gate=fs::read_to_string(format!("{R}/diagnostic-run/{name}/stderr.log")).unwrap();assert_eq!(gate.lines().filter(|l|l.starts_with("Events ")).collect::<Vec<_>>(),vec!["Events disabled","Events enabled","Events disabled"]);
  let loss=read(path("loss-"));let raw=fs::read_to_string(path("decode-")).unwrap();let(mut samples,mut unknown)=(0u64,0u64);let mut tids=BTreeSet::new();let mut symbols=BTreeMap::<String,u64>::new();
  for line in raw.lines().filter(|l|!l.is_empty()&&!l.starts_with('#')){let f=line.split_whitespace().collect::<Vec<_>>();assert!(f.len()>=6);let(p,t)=f[0].split_once('/').unwrap();assert_eq!(p.parse::<u64>().unwrap(),pid);let tid=t.parse::<u64>().unwrap();let cpu=f[1].trim_matches(&['[',']'][..]).parse::<u64>().unwrap();assert!(cpu<32);if tid!=pid{assert_eq!(workers.get(&tid),Some(&cpu));}assert_eq!(f[3].parse::<u64>().unwrap(),16000000);u64::from_str_radix(f[4].trim_start_matches("0x"),16).unwrap();let symbol=f[5..].join(" ");unknown+=u64::from(symbol.contains("unknown"));*symbols.entry(format!("{:#}",rustc_demangle::demangle(&symbol))).or_default()+=1;samples+=1;tids.insert(tid);}
  for tid in&tids{assert!(metadata.contains(&format!("{pid}/{tid}")));}let pass=samples>=1000&&unknown*100<=samples*5&&loss["zero_lost"]==true;quality&=pass;let mut ranks=symbols.into_iter().collect::<Vec<_>>();ranks.sort_by(|a,b|b.1.cmp(&a.1));profiles.push(json!({"mode":m,"samples":samples,"unknown_samples":unknown,"zero_LOST":loss["zero_lost"],"quality_passed":pass,"top_symbols":ranks.into_iter().take(30).collect::<Vec<_>>(),"data_sha256":hash(format!("{R}/perf/{name}.data"))}));
 }
 save("diagnostic-analysis.json",json!({"passed_data_validation":true,"quality_passed":quality,"command_seconds":seconds,"stats":stats,"profiles":profiles,"caller_rows":callers,"checked_queries":1380,"total_queries_including_screen":2609,"new_proofs":0,"adoption":false,"screen_decision_unchanged":true}));println!("21receipts/1380 queries checked; quality={quality}");for v in stats{println!("counters {v}");}for p in profiles{println!("mode{} samples{} top{}",p["mode"],p["samples"],json!(&p["top_symbols"].as_array().unwrap()[..8]));}
}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("analyze")=>analyze(),_=>panic!("prepare/analyze")}}
